package org.apache.commons.lang3.math;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_isNumber_TriageGen0Test {











    @Test
    public void testIsNumber_TypeQualifiers() {
        // d, D, f, F
        assertTrue(NumberUtils.isNumber("123d"));
        assertTrue(NumberUtils.isNumber("123D"));
        assertTrue(NumberUtils.isNumber("123f"));
        assertTrue(NumberUtils.isNumber("123F"));
        assertTrue(NumberUtils.isNumber("123.45f"));

        // l, L (only if no exponent and no decimal point)
        assertTrue(NumberUtils.isNumber("123l"));
        assertTrue(NumberUtils.isNumber("123L"));
        assertFalse(NumberUtils.isNumber("123.45l"));
        assertFalse(NumberUtils.isNumber("123e10l"));

        // Edge cases for qualifiers
        assertFalse(NumberUtils.isNumber("f"));
        assertFalse(NumberUtils.isNumber("l"));
    }




}

package org.apache.commons.lang3.math;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_isNumber_TriageGen0Test {













    @Test
    public void testIsNumber_ComplexEdgeCases() {
        // Test the logic: while (i < sz || (i < sz + 1 && allowSigns && !foundDigit))
        // This targets the specific branch where a sign is allowed after E but no digit is found yet
        assertFalse(NumberUtils.isNumber("1E-"));
        assertFalse(NumberUtils.isNumber("1E+"));

        // Test the loop termination and the trailing char logic
        assertTrue(NumberUtils.isNumber("123"));

        // Test sign at start for hex
        assertTrue(NumberUtils.isNumber("-0x123"));

        // Test single digit with sign
        assertTrue(NumberUtils.isNumber("-1"));

        // Test multiple decimal points or decimals in exponent
        assertFalse(NumberUtils.isNumber("1.2e3.4"));

        // Test non-digit trailing characters
        assertFalse(NumberUtils.isNumber("123x"));
        assertFalse(NumberUtils.isNumber("123?"));
    }


}

