public class NumberUtils_isNumber_TriageGen0Test {















    @Test
    public void testIsNumber_SpecificBranchCoverage() {
        // Ensure 'foundDigit' logic works for '.', 'e', etc.
        assertFalse(NumberUtils.isNumber("."));
        assertFalse(NumberUtils.isNumber("e10"));
        assertTrue(NumberUtils.isNumber("1."));

        // Test the i < chars.length block for decimals
        // The code returns foundDigit if last char is '.'
        assertTrue(NumberUtils.isNumber("1.")); 
        assertFalse(NumberUtils.isNumber(".")); // foundDigit is false

        // Test the allowSigns logic at the end
        // allowSigns is true if it ends in 'E'
        assertFalse(NumberUtils.isNumber("123E"));
    }
}
